_pkg = _types.ModuleType("app")
_pkg.__path__ = []
_sys.modules["app"] = _pkg

for _name in _ORDER:
    _full = "app." + _name
    _mod = _types.ModuleType(_full)
    _mod.__package__ = "app"
    _mod.__file__ = "app/" + _name + ".py"
    _sys.modules[_full] = _mod
    exec(compile(_b64.b64decode(_SRC[_name]).decode("utf-8"), _mod.__file__, "exec"),
         _mod.__dict__)
    setattr(_pkg, _name, _mod)

