GREEN, RED, BLUE, ORANGE, PURPLE = "#26a65b", "#e0484b", "#4c8bf5", "#f0a500", "#a06cd5"


# ------------------------------------------------------------------ الحماية
def gate() -> bool:
    if not config.APP_PASSWORD:
        return True
    if st.session_state.get("auth"):
        return True
    st.title("🔒 تسجيل الدخول")
    pw = st.text_input("كلمة السر", type="password")
    if st.button("دخول", type="primary"):
        if pw == config.APP_PASSWORD:
            st.session_state["auth"] = True
            st.rerun()
        else:
            st.error("كلمة السر غلط")
    return False


if not gate():
    st.stop()

data.init_db()


# ------------------------------------------------------------------ الكاش
@st.cache_data(ttl=600, show_spinner=False)
def hist(symbol: str, _v: int = 0) -> pd.DataFrame:
    return data.get_history(symbol)


@st.cache_data(ttl=600, show_spinner=False)
def enriched(symbol: str, _v: int = 0) -> pd.DataFrame:
    df = data.get_history(symbol)
    return indicators.enrich(df) if df is not None and not df.empty else pd.DataFrame()


@st.cache_data(ttl=900, show_spinner=False)
def overview(_v: int = 0) -> dict:
    return scanner.market_overview()


def bump_cache():
    st.session_state["cache_v"] = st.session_state.get("cache_v", 0) + 1
    st.cache_data.clear()


CV = st.session_state.get("cache_v", 0)
UNI = universe.load()


# ------------------------------------------------------------------ الشارت
def price_chart(d: pd.DataFrame, symbol: str, show: dict, lookback: int = 250) -> go.Figure:
    v = d.tail(lookback)
    fig = make_subplots(rows=4, cols=1, shared_xaxes=True,
                        row_heights=[0.55, 0.15, 0.15, 0.15], vertical_spacing=0.02,
                        subplot_titles=("", "الحجم", "RSI", "MACD"))

    fig.add_trace(go.Candlestick(
        x=v.index, open=v.Open, high=v.High, low=v.Low, close=v.Close, name=symbol,
        increasing_line_color=GREEN, decreasing_line_color=RED,
        increasing_fillcolor=GREEN, decreasing_fillcolor=RED), row=1, col=1)

    if show.get("ma"):
        for n, col in ((20, BLUE), (50, ORANGE), (200, PURPLE)):
            if f"SMA{n}" in v and v[f"SMA{n}"].notna().any():
                fig.add_trace(go.Scatter(x=v.index, y=v[f"SMA{n}"], name=f"متوسط {n}",
                                         line=dict(width=1.4, color=col)), row=1, col=1)
    if show.get("ema21") and "EMA21" in v:
        fig.add_trace(go.Scatter(x=v.index, y=v.EMA21, name="EMA21",
                                 line=dict(width=1.2, color="#00c2a8", dash="dot")), row=1, col=1)
    if show.get("bb"):
        fig.add_trace(go.Scatter(x=v.index, y=v.BB_UP, name="بولنجر علوي",
                                 line=dict(width=1, color="rgba(150,150,150,.55)")), row=1, col=1)
        fig.add_trace(go.Scatter(x=v.index, y=v.BB_LOW, name="بولنجر سفلي", fill="tonexty",
                                 fillcolor="rgba(120,120,120,.08)",
                                 line=dict(width=1, color="rgba(150,150,150,.55)")), row=1, col=1)
    if show.get("vwap") and "VWAP20" in v:
        fig.add_trace(go.Scatter(x=v.index, y=v.VWAP20, name="VWAP20",
                                 line=dict(width=1.1, color="#ffd166", dash="dash")), row=1, col=1)

    _lv = show.get("levels")
    if _lv is not None and len(_lv):
        for _, r in _lv.iterrows():
            c = RED if r["kind"] == "مقاومة" else GREEN
            fig.add_hline(y=r["level"], line=dict(color=c, width=1, dash="dash"),
                          opacity=0.35 + min(r["strength"], 6) / 15,
                          annotation_text=f"{r['kind']} {r['level']:.2f} ({r['touches']}×)",
                          annotation_position="top left", annotation_font_size=10,
                          annotation_font_color=c, row=1, col=1)

    if show.get("channel"):
        ch = show["channel"]
        for key, dash, nm in (("line", "solid", "خط الاتجاه"),
                              ("line_up", "dot", "أعلى القناة"),
                              ("line_dn", "dot", "أسفل القناة")):
            s = ch[key]
            s = s[s.index.isin(v.index)]
            fig.add_trace(go.Scatter(x=s.index, y=s.values, name=nm,
                                     line=dict(width=1, color="rgba(255,255,255,.45)", dash=dash),
                                     showlegend=(key == "line")), row=1, col=1)

    if show.get("markers") is not None and len(show["markers"]):
        m = show["markers"]
        m = m[m.index.isin(v.index)]
        buys = m[m["side"] == "شراء"]
        sells = m[m["side"] == "بيع"]
        if len(buys):
            fig.add_trace(go.Scatter(x=buys.index, y=v.loc[buys.index, "Low"] * 0.985,
                                     mode="markers", name="إشارة شراء", text=buys["label"],
                                     hovertemplate="%{text}<extra></extra>",
                                     marker=dict(symbol="triangle-up", size=12, color=GREEN)),
                          row=1, col=1)
        if len(sells):
            fig.add_trace(go.Scatter(x=sells.index, y=v.loc[sells.index, "High"] * 1.015,
                                     mode="markers", name="إشارة بيع", text=sells["label"],
                                     hovertemplate="%{text}<extra></extra>",
                                     marker=dict(symbol="triangle-down", size=12, color=RED)),
                          row=1, col=1)

    vol_colors = np.where(v.Close >= v.Open, GREEN, RED)
    fig.add_trace(go.Bar(x=v.index, y=v.Volume, name="الحجم",
                         marker_color=vol_colors, opacity=0.55), row=2, col=1)
    if "VOL_SMA20" in v:
        fig.add_trace(go.Scatter(x=v.index, y=v.VOL_SMA20, name="متوسط الحجم",
                                 line=dict(width=1, color=ORANGE)), row=2, col=1)

    fig.add_trace(go.Scatter(x=v.index, y=v.RSI, name="RSI",
                             line=dict(width=1.4, color=PURPLE)), row=3, col=1)
    for y, c in ((70, RED), (30, GREEN), (50, "rgba(255,255,255,.25)")):
        fig.add_hline(y=y, line=dict(color=c, width=1, dash="dot"), row=3, col=1)

    hist_colors = np.where(v.MACD_HIST >= 0, GREEN, RED)
    fig.add_trace(go.Bar(x=v.index, y=v.MACD_HIST, name="الهيستوجرام",
                         marker_color=hist_colors, opacity=0.6), row=4, col=1)
    fig.add_trace(go.Scatter(x=v.index, y=v.MACD, name="MACD",
                             line=dict(width=1.3, color=BLUE)), row=4, col=1)
    fig.add_trace(go.Scatter(x=v.index, y=v.MACD_SIG, name="الإشارة",
                             line=dict(width=1.2, color=ORANGE)), row=4, col=1)

    fig.update_layout(height=820, template="plotly_dark", hovermode="x unified",
                      xaxis_rangeslider_visible=False, margin=dict(l=60, r=20, t=30, b=10),
                      legend=dict(orientation="h", y=1.03, x=1, xanchor="right"))
    fig.update_yaxes(range=[0, 100], row=3, col=1)
    # إخفاء أيام العطلة (الجمعة والسبت) من المحور
    fig.update_xaxes(rangebreaks=[dict(bounds=["fri", "sun"])])
    return fig


